public class ReportGenerator { public static String batchPrint(LibraryMember[] members) { StringBuilder report = new StringBuilder(); for (LibraryMember m : members) { report.append(m.displayInfo()); if (m instanceof StudentMember) { StudentMember sm = (StudentMember) m; report.append(" [Course via downcast: ").append(sm.getCourse()).append("]"); } report.append(" | "); } return report.toString(); } public static void main(String[] args) { LibraryMember[] members = {new LibraryMember("LB5", 3), new StudentMember("STU6", 3, "ECE")}; String reportOutput = batchPrint(members); System.out.println(reportOutput); } }